using System.Text;
string folder=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);
try
{
    byte[] bytes=Encoding.UTF8.GetBytes("Chào");
    using var input=new SmallReads(bytes);
    using var output=new MemoryStream();
    byte[] buffer=new byte[8];int n;
    while((n=await input.ReadAsync(buffer))>0)await output.WriteAsync(buffer.AsMemory(0,n));
    Console.WriteLine(Encoding.UTF8.GetString(output.ToArray()));
    string file=Path.Combine(folder,"demo.txt");
    await File.WriteAllTextAsync(file,"ABCDE",new UTF8Encoding(false));
    using(var writer=File.OpenWrite(file))await writer.WriteAsync(Encoding.UTF8.GetBytes("X"));
    Console.WriteLine(await File.ReadAllTextAsync(file));
    using(var writer=File.Create(file))await writer.WriteAsync(Encoding.UTF8.GetBytes("X"));
    Console.WriteLine(await File.ReadAllTextAsync(file));
    using var pieces=new SmallReads(bytes);using var reader=new StreamReader(pieces,Encoding.UTF8);
    Console.WriteLine(await reader.ReadToEndAsync());
}
finally{Directory.Delete(folder,true);}
class SmallReads(byte[] bytes):MemoryStream(bytes)
{
 public override int Read(byte[] b,int o,int c)=>base.Read(b,o,Math.Min(c,1));
 public override int Read(Span<byte> b)=>base.Read(b[..Math.Min(1,b.Length)]);
 public override ValueTask<int> ReadAsync(Memory<byte> b,CancellationToken t=default)=>base.ReadAsync(b[..Math.Min(1,b.Length)],t);
}

